B=[
('الْأَخَوَانِ','İki kardeş',[
('كَانَ لِهَارُونَ الرَّشِيدِ ابْنَانِ مِنْ أُمَّيْنِ مُخْتَلِفَتَيْنِ: الْأَمِينُ وَالْمَأْمُونُ.','Hârûnürreşîd’in farklı annelerden iki oğlu vardı: Emîn ve Me’mûn.'),
('كَانَتْ أُمُّ الْأَمِينِ زُبَيْدَةَ، وَهِيَ عَرَبِيَّةٌ مِنْ بَنِي هَاشِمٍ.','Emîn’in annesi Haşimoğullarından Arap bir kadın olan Zübeyde idi.'),
('وَكَانَتْ أُمُّ الْمَأْمُونِ جَارِيَةً فَارِسِيَّةً مَاتَتْ بَعْدَ وِلَادَتِهِ.','Me’mûn’un annesi onu doğurduktan sonra ölen Farslı bir cariyeydi.'),
('وَكَانَ الْمَأْمُونُ أَكْبَرَ سِنًّا وَأَكْثَرَ عِلْمًا وَعَقْلًا.','Me’mûn yaşça daha büyük, ilim ve akılca daha üstündü.'),
('وَكَانَ الْأَمِينُ يُحِبُّ اللَّهْوَ وَالصَّيْدَ، وَلَكِنَّ أُمَّهُ كَانَتْ قَوِيَّةً.','Emîn eğlenceyi ve avı severdi ama annesi güçlüydü.'),
('فَجَعَلَ الرَّشِيدُ الْأَمِينَ وَلِيَّ عَهْدِهِ الْأَوَّلَ، وَالْمَأْمُونَ بَعْدَهُ.','Reşîd Emîn’i birinci veliaht, Me’mûn’u da ondan sonraki veliaht yaptı.')]),
('الْعَهْدُ فِي الْكَعْبَةِ','Kâbe’deki ahitname',[
('وَخَافَ الرَّشِيدُ أَنْ يَتَنَازَعَ ابْنَاهُ بَعْدَهُ.','Reşîd oğullarının kendisinden sonra çekişmesinden korktu.'),
('فَكَتَبَ عَهْدًا يَقُولُ: لِلْأَمِينِ بَغْدَادُ وَالْخِلَافَةُ، وَلِلْمَأْمُونِ خُرَاسَانُ وَالْمَشْرِقُ.','Bir ahitname yazdı: Bağdat ve hilafet Emîn’in, Horasan ve doğu Me’mûn’un.'),
('وَأَشْهَدَ عَلَيْهِ الْعُلَمَاءَ، وَعَلَّقَهُ فِي الْكَعْبَةِ.','Âlimleri buna şahit tuttu ve onu Kâbe’ye astı.'),
('وَحَلَفَ الْأَخَوَانِ أَلَّا يَغْدِرَ أَحَدُهُمَا بِالْآخَرِ.','İki kardeş birbirlerine ihanet etmeyeceklerine yemin ettiler.'),
('وَلَكِنْ يُرْوَى أَنَّ الْكِتَابَ سَقَطَ مِنَ الْكَعْبَةِ، فَقَالَ النَّاسُ: «هَذَا عَهْدٌ لَا يَتِمُّ.»','Ama rivayete göre yazı Kâbe’den düştü; insanlar dedi ki: “Bu ahit yerine gelmeyecek.”'),
('ثُمَّ مَاتَ الرَّشِيدُ فِي طُوسَ سَنَةَ مِائَةٍ وَثَلَاثٍ وَتِسْعِينَ.','Sonra Reşîd 193 yılında Tûs’ta öldü.')]),
('الْغَدْرُ','İhanet',[
('فَصَارَ الْأَمِينُ خَلِيفَةً فِي بَغْدَادَ، وَبَقِيَ الْمَأْمُونُ فِي مَرْوَ.','Emîn Bağdat’ta halife oldu, Me’mûn da Merv’de kaldı.'),
('وَكَانَ وَزِيرُ الْأَمِينِ الْفَضْلُ بْنُ الرَّبِيعِ يُخَوِّفُهُ مِنْ أَخِيهِ.','Emîn’in veziri Fazl b. Rebî‘ onu kardeşinden korkutuyordu.'),
('فَخَلَعَ الْأَمِينُ أَخَاهُ مِنْ وِلَايَةِ الْعَهْدِ، وَجَعَلَ ابْنَهُ الصَّغِيرَ مَكَانَهُ.','Emîn kardeşini veliahtlıktan azletti ve yerine küçük oğlunu getirdi.'),
('وَأَرْسَلَ مَنْ يَأْتِي بِكِتَابِ الْعَهْدِ مِنَ الْكَعْبَةِ، فَمَزَّقَهُ.','Ahitnameyi Kâbe’den getirecek birini gönderdi ve onu yırttı.'),
('وَكَانَ مَعَ الْمَأْمُونِ وَزِيرٌ ذَكِيٌّ هُوَ الْفَضْلُ بْنُ سَهْلٍ، فَقَالَ لَهُ: «اصْبِرْ، فَإِنَّ الْحَقَّ مَعَكَ.»','Me’mûn’un yanında Fazl b. Sehl adında zeki bir vezir vardı; ona dedi ki: “Sabret, çünkü hak seninle.”'),
('وَفِي رِوَايَةِ زَيْدَانَ، يَتَحَرَّكُ بَيْنَ الْقَصْرَيْنِ جَوَاسِيسُ وَرُسُلٌ وَعُشَّاقٌ، فَيَتَدَاخَلُ الْحُبُّ وَالسِّيَاسَةُ.','Zeydân’ın romanında iki saray arasında casuslar, elçiler ve âşıklar dolaşır; aşk ile siyaset iç içe geçer.')]),
('الْحَرْبُ','Savaş',[
('فَأَرْسَلَ الْأَمِينُ جَيْشًا كَبِيرًا إِلَى خُرَاسَانَ بِقِيَادَةِ عَلِيِّ بْنِ عِيسَى.','Emîn Ali b. Îsâ komutasında Horasan’a büyük bir ordu gönderdi.'),
('وَخَرَجَ إِلَيْهِ مِنْ جَيْشِ الْمَأْمُونِ قَائِدٌ شُجَاعٌ هُوَ طَاهِرُ بْنُ الْحُسَيْنِ، بِجَيْشٍ صَغِيرٍ.','Me’mûn’un ordusundan ona karşı küçük bir orduyla cesur bir komutan çıktı: Tâhir b. Hüseyin.'),
('فَانْتَصَرَ طَاهِرٌ عِنْدَ الرَّيِّ، وَقُتِلَ عَلِيُّ بْنُ عِيسَى.','Tâhir Rey yakınında galip geldi ve Ali b. Îsâ öldürüldü.'),
('ثُمَّ سَارَ طَاهِرٌ نَحْوَ بَغْدَادَ، وَحَاصَرَهَا سَنَةً كَامِلَةً.','Sonra Tâhir Bağdat’a doğru yürüdü ve onu tam bir yıl kuşattı.'),
('فَخَرِبَتْ أَحْيَاءٌ كَثِيرَةٌ مِنْ بَغْدَادَ، وَجَاعَ أَهْلُهَا.','Bağdat’ın birçok mahallesi harap oldu ve halkı açlık çekti.'),
('وَحَزِنَ الشُّعَرَاءُ عَلَى الْمَدِينَةِ الْجَمِيلَةِ، وَبَكَوْهَا فِي قَصَائِدِهِمْ.','Şairler güzel şehre üzüldüler ve kasidelerinde ona ağladılar.')]),
('الْمَأْمُونُ','Me’mûn',[
('وَفِي سَنَةِ مِائَةٍ وَثَمَانٍ وَتِسْعِينَ سَقَطَتْ بَغْدَادُ، وَقُتِلَ الْأَمِينُ.','198 yılında Bağdat düştü ve Emîn öldürüldü.'),
('فَحَزِنَ الْمَأْمُونُ عَلَى أَخِيهِ، وَقَالَ: «مَا كُنْتُ أُرِيدُ قَتْلَهُ.»','Me’mûn kardeşine üzüldü ve dedi ki: “Onun öldürülmesini istemiyordum.”'),
('وَصَارَ الْمَأْمُونُ خَلِيفَةً، وَأَكْرَمَ زُبَيْدَةَ أُمَّ أَخِيهِ.','Me’mûn halife oldu ve kardeşinin annesi Zübeyde’ye saygı gösterdi.'),
('وَكَانَ مُحِبًّا لِلْعِلْمِ، فَأَسَّسَ بَيْتَ الْحِكْمَةِ فِي بَغْدَادَ.','İlmi seven biriydi; Bağdat’ta Beytü’l-Hikme’yi kurdu.'),
('وَجَمَعَ فِيهِ الْعُلَمَاءَ، وَتُرْجِمَتْ فِيهِ كُتُبُ الْيُونَانِ وَالْفُرْسِ وَالْهِنْدِ إِلَى الْعَرَبِيَّةِ.','Oraya âlimleri topladı; Yunan, Fars ve Hint kitapları orada Arapçaya çevrildi.'),
('فَصَارَ عَهْدُهُ مِنْ أَزْهَى عُهُودِ الْعِلْمِ فِي التَّارِيخِ، بَعْدَ أَنْ كَانَ بَدْؤُهُ حَرْبًا بَيْنَ أَخَوَيْنِ.','Böylece başlangıcı iki kardeş arasında bir savaş olan devri, tarihte ilmin en parlak devirlerinden biri oldu.')]),
]
